// z2ui5_cci.cc.Util - the few helpers every control in this library needs.                                                                                                                                                                                    
//                                                                                                                                                                                                                                                             
// It exists because most controls here wrap a third-party library that lives                                                                                                                                                                                  
// on a CDN, and because several of them have to find another control by the id                                                                                                                                                                                
// an abap2UI5 app gave it. Both jobs are easy to get subtly wrong (loading the                                                                                                                                                                                
// same script twice, resolving an id against the wrong view), so they live in                                                                                                                                                                                 
// one place.                                                                                                                                                                                                                                                  
//                                                                                                                                                                                                                                                             
// Deliberately NOT a dependency on z2ui5/core/Lib: that module is                                                                                                                                                                                             
// frontend-internal and not part of the public contract, so a control shipped                                                                                                                                                                                 
// from its own BSP must not reach into it - a refactor there would break the                                                                                                                                                                                  
// control silently.                                                                                                                                                                                                                                           
sap.ui.define(["sap/ui/core/Element", "z2ui5_cci/cc/LibUrls"], (Element, LibUrls) => {                                                                                                                                                                         
  "use strict";                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                               
  // one promise per URL, so ten charts on one page load Chart.js once                                                                                                                                                                                         
  const scripts = new Map();                                                                                                                                                                                                                                   
  const styles = new Map();                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                               
  // URL -> Subresource Integrity hash (sha384) of every library URL the CDN                                                                                                                                                                                   
  // build pins, generated by tools/vendor.mjs from the files in node_modules.                                                                                                                                                                                 
  // Looked up by the exact URL, so a liburl/cssurl an app overrides loads                                                                                                                                                                                     
  // without one - the hash belongs to the pinned file, not to whatever the                                                                                                                                                                                    
  // app points at. Empty on the local build: those files come from this BSP.                                                                                                                                                                                  
  const INTEGRITY = (LibUrls && LibUrls.integrity) || {};                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
  const logError = (message, error) =>                                                                                                                                                                                                                         
    console.error(error === undefined ? message : `${message}:`, error ?? "");                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
  // Guards async continuations (script load, resize observer) against a                                                                                                                                                                                       
  // control that was torn down in the meantime. ManagedObject.isDestroyed( )                                                                                                                                                                                  
  // arrived in UI5 1.93; before it the flag is the only way to ask.                                                                                                                                                                                           
  const isDestroyed = (obj) =>                                                                                                                                                                                                                                 
    Boolean(                                                                                                                                                                                                                                                   
      obj &&                                                                                                                                                                                                                                                   
        (typeof obj.isDestroyed === "function" ? obj.isDestroyed() : obj.bIsDestroyed),                                                                                                                                                                        
    );                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
  // With an integrity hash the browser refuses a file whose bytes differ from                                                                                                                                                                                 
  // the ones this repository was tested against - a compromised or altered CDN                                                                                                                                                                                
  // copy fails to load instead of running. A cross-origin file is only                                                                                                                                                                                        
  // checked when it is fetched in CORS mode, hence crossorigin="anonymous"                                                                                                                                                                                    
  // (jsDelivr answers with Access-Control-Allow-Origin: *).                                                                                                                                                                                                   
  function applyIntegrity(tag, integrity) {                                                                                                                                                                                                                    
    if (!integrity) return;                                                                                                                                                                                                                                    
    tag.setAttribute("integrity", integrity);                                                                                                                                                                                                                  
    tag.setAttribute("crossorigin", "anonymous");                                                                                                                                                                                                              
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // A bare number is treated as px, everything else is passed through.                                                                                                                                                                                        
  const toCssSize = (val) =>                                                                                                                                                                                                                                   
    val === undefined || val === null || val === ""                                                                                                                                                                                                            
      ? ""                                                                                                                                                                                                                                                     
      : /^-?\d+(\.\d+)?$/.test(String(val))                                                                                                                                                                                                                    
        ? `${val}px`                                                                                                                                                                                                                                           
        : String(val);                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
  // The pinned hash of a URL, "" for any other - for a file a control fetches                                                                                                                                                                                 
  // itself (BarcodeScanner's WebAssembly module): fetch(url, { integrity }).                                                                                                                                                                                  
  const integrityOf = (url) => INTEGRITY[url] || "";                                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
  // Loads a script tag once and resolves when it is ready.                                                                                                                                                                                                    
  //                                                                                                                                                                                                                                                           
  // `isReady` lets a caller skip the whole thing when the library is already                                                                                                                                                                                  
  // on the page - a system that ships Chart.js in its own BSP or in the                                                                                                                                                                                       
  // Launchpad shell never has to reach a CDN. `integrity` defaults to the                                                                                                                                                                                     
  // pinned hash of the URL, see INTEGRITY.                                                                                                                                                                                                                    
  function loadScript(url, isReady, integrity = INTEGRITY[url]) {                                                                                                                                                                                              
    if (typeof isReady === "function" && isReady()) return Promise.resolve();                                                                                                                                                                                  
    if (!url) return Promise.reject(new Error("no library URL configured"));                                                                                                                                                                                   
    if (scripts.has(url)) return scripts.get(url);                                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
    const pending = new Promise((resolve, reject) => {                                                                                                                                                                                                         
      const tag = document.createElement("script");                                                                                                                                                                                                            
      applyIntegrity(tag, integrity);                                                                                                                                                                                                                          
      tag.src = url;                                                                                                                                                                                                                                           
      tag.async = true;                                                                                                                                                                                                                                        
      tag.addEventListener("load", () => resolve());                                                                                                                                                                                                           
      tag.addEventListener("error", () =>                                                                                                                                                                                                                      
        reject(new Error(`could not load ${url}`)),                                                                                                                                                                                                            
      );                                                                                                                                                                                                                                                       
      document.head.appendChild(tag);                                                                                                                                                                                                                          
    });                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
    // A failed load must not be cached as failed forever - a later render                                                                                                                                                                                     
    // (or a corrected URL) has to be able to try again.                                                                                                                                                                                                       
    pending.catch(() => scripts.delete(url));                                                                                                                                                                                                                  
    scripts.set(url, pending);                                                                                                                                                                                                                                 
    return pending;                                                                                                                                                                                                                                            
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // Same for a stylesheet. Resolving on load is rarely interesting for CSS,                                                                                                                                                                                   
  // but a caller that wants to render only afterwards can await it.                                                                                                                                                                                           
  function loadStyle(url, integrity = INTEGRITY[url]) {                                                                                                                                                                                                        
    if (!url) return Promise.resolve();                                                                                                                                                                                                                        
    if (styles.has(url)) return styles.get(url);                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
    const pending = new Promise((resolve, reject) => {                                                                                                                                                                                                         
      const tag = document.createElement("link");                                                                                                                                                                                                              
      tag.rel = "stylesheet";                                                                                                                                                                                                                                  
      applyIntegrity(tag, integrity);                                                                                                                                                                                                                          
      tag.href = url;                                                                                                                                                                                                                                          
      tag.addEventListener("load", () => resolve());                                                                                                                                                                                                           
      tag.addEventListener("error", () =>                                                                                                                                                                                                                      
        reject(new Error(`could not load ${url}`)),                                                                                                                                                                                                            
      );                                                                                                                                                                                                                                                       
      document.head.appendChild(tag);                                                                                                                                                                                                                          
    });                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
    pending.catch(() => styles.delete(url));                                                                                                                                                                                                                   
    styles.set(url, pending);                                                                                                                                                                                                                                  
    return pending;                                                                                                                                                                                                                                            
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // Loads a list of scripts strictly in order. Plugins usually have to come                                                                                                                                                                                   
  // after the library they extend, so Promise.all is wrong here.                                                                                                                                                                                              
  function loadScripts(urls) {                                                                                                                                                                                                                                 
    return urls.reduce(                                                                                                                                                                                                                                        
      (chain, url) => chain.then(() => loadScript(url)),                                                                                                                                                                                                       
      Promise.resolve(),                                                                                                                                                                                                                                       
    );                                                                                                                                                                                                                                                         
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // The view a control was rendered into - the scope an abap2UI5 app's                                                                                                                                                                                        
  // control ids are relative to.                                                                                                                                                                                                                              
  function ownerView(control) {                                                                                                                                                                                                                                
    let node = control;                                                                                                                                                                                                                                        
    while (node) {                                                                                                                                                                                                                                             
      if (node.isA && node.isA("sap.ui.core.mvc.View")) return node;                                                                                                                                                                                           
      node = node.getParent ? node.getParent() : null;                                                                                                                                                                                                         
    }                                                                                                                                                                                                                                                          
    return null;                                                                                                                                                                                                                                               
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // The control registered under a full id. Element.getElementById arrived                                                                                                                                                                                    
  // in UI5 1.119; before it the registry is reached through                                                                                                                                                                                                   
  // sap.ui.getCore().byId - the same fallback abap2UI5's own frontend uses                                                                                                                                                                                    
  // (app/webapp/core/Env.js).                                                                                                                                                                                                                                 
  function byGlobalId(id) {                                                                                                                                                                                                                                    
    if (Element.getElementById) return Element.getElementById(id) || null;                                                                                                                                                                                     
    const core = sap.ui.getCore ? sap.ui.getCore() : null;                                                                                                                                                                                                     
    return (core && core.byId && core.byId(id)) || null;                                                                                                                                                                                                       
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // Every control whose id ends in `suffix`. Element.registry exists from UI5                                                                                                                                                                                 
  // 1.84 on; older releases have no public list of controls, so the rendered                                                                                                                                                                                  
  // DOM serves as the index there - a control the app points at by id (a                                                                                                                                                                                      
  // table to export, a field to validate, a tour step) is on the page.                                                                                                                                                                                        
  function bySuffix(suffix) {                                                                                                                                                                                                                                  
    if (Element.registry) {                                                                                                                                                                                                                                    
      return Element.registry.filter((el) => el.getId().endsWith(suffix));                                                                                                                                                                                     
    }                                                                                                                                                                                                                                                          
    const hits = [];                                                                                                                                                                                                                                           
    document.querySelectorAll("[id]").forEach((node) => {                                                                                                                                                                                                      
      if (!node.id.endsWith(suffix)) return;                                                                                                                                                                                                                   
      const control = byGlobalId(node.id);                                                                                                                                                                                                                     
      if (control && !hits.includes(control)) hits.push(control);                                                                                                                                                                                              
    });                                                                                                                                                                                                                                                        
    return hits;                                                                                                                                                                                                                                               
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // Resolves the id an abap2UI5 app wrote in the view (`id = 'myTable'`) to                                                                                                                                                                                   
  // the control instance.                                                                                                                                                                                                                                     
  //                                                                                                                                                                                                                                                           
  // Three attempts, because the same app id can end up in three different                                                                                                                                                                                     
  // scopes: the main view, a nested view, or a popup/popover fragment. The                                                                                                                                                                                    
  // last attempt looks for an id ending in `--<id>`, which covers every                                                                                                                                                                                       
  // prefixing scheme without the control having to know which view it landed                                                                                                                                                                                  
  // in - that is what the old z2ui5.oView/oViewNest/oViewPopup cascade was                                                                                                                                                                                    
  // doing by hand.                                                                                                                                                                                                                                            
  function resolveControl(control, id) {                                                                                                                                                                                                                       
    if (!id) return null;                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
    const view = ownerView(control);                                                                                                                                                                                                                           
    const local = view && view.byId(id);                                                                                                                                                                                                                       
    if (local) return local;                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                               
    const global = byGlobalId(id);                                                                                                                                                                                                                             
    if (global) return global;                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
    try {                                                                                                                                                                                                                                                      
      const hits = bySuffix(`--${id}`);                                                                                                                                                                                                                        
      if (hits.length === 1) return hits[0];                                                                                                                                                                                                                   
      if (hits.length > 1) {                                                                                                                                                                                                                                   
        logError(                                                                                                                                                                                                                                              
          `Util.resolveControl: id '${id}' is ambiguous, ${hits.length} controls match`,                                                                                                                                                                       
        );                                                                                                                                                                                                                                                     
      }                                                                                                                                                                                                                                                        
    } catch (e) {                                                                                                                                                                                                                                              
      // not finding the control is a normal outcome, not a reason to throw                                                                                                                                                                                    
      // out of a hook                                                                                                                                                                                                                                         
      logError("Util.resolveControl: control lookup failed", e);                                                                                                                                                                                               
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    return null;                                                                                                                                                                                                                                               
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // The last value each `trigger` binding had - see triggerFired.                                                                                                                                                                                             
  const triggerMemory = new Map();                                                                                                                                                                                                                             
  const triggerSeen = new WeakSet();                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
  // Decides whether a new value of an integer `trigger` property starts the                                                                                                                                                                                   
  // control's action (DriverJs: the tour, Validator: the check). 0 never does.                                                                                                                                                                                
  //                                                                                                                                                                                                                                                           
  // After its first value a control acts on every CHANGE of the value. The                                                                                                                                                                                    
  // first value an instance receives is the hard one: a view_display builds a                                                                                                                                                                                 
  // new instance, and that instance is handed the value the model already                                                                                                                                                                                     
  // had - after a navigation back, the trigger the user raised minutes ago.                                                                                                                                                                                   
  // Acting on it would restart the tour or re-validate on every rebuild. Not                                                                                                                                                                                  
  // acting on it at all would swallow an app that raises the trigger in the                                                                                                                                                                                   
  // same roundtrip that first displays the view. So the value is remembered                                                                                                                                                                                   
  // per control class and binding path, across instances: a first value that                                                                                                                                                                                  
  // is what an earlier instance at the same path last had is the old state                                                                                                                                                                                    
  // and is skipped; any other value is new and is acted on.                                                                                                                                                                                                   
  //                                                                                                                                                                                                                                                           
  // The memory lives as long as the page. An unbound (literal) trigger has no                                                                                                                                                                                 
  // path and therefore no memory - a view that says trigger="1" asks for the                                                                                                                                                                                  
  // action on every display, and gets it.                                                                                                                                                                                                                     
  function triggerFired(control, value, previous, property = "trigger") {                                                                                                                                                                                      
    const first = !triggerSeen.has(control);                                                                                                                                                                                                                   
    triggerSeen.add(control);                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
    const path = control.getBindingPath ? control.getBindingPath(property) : null;                                                                                                                                                                             
    const info = path && control.getBindingInfo ? control.getBindingInfo(property) : null;                                                                                                                                                                     
    const model = (info && info.parts && info.parts[0] && info.parts[0].model) || "";                                                                                                                                                                          
    const key = path ? `${control.getMetadata().getName()}|${property}|${model}>${path}` : "";                                                                                                                                                                 
                                                                                                                                                                                                                                                               
    const remembered = key ? triggerMemory.get(key) : undefined;                                                                                                                                                                                               
    if (key) triggerMemory.set(key, value);                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                               
    if (!(value > 0)) return false;                                                                                                                                                                                                                            
    if (first) return value !== remembered;                                                                                                                                                                                                                    
    return value !== previous;                                                                                                                                                                                                                                 
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  // The DOMPurify options of every control that renders HTML it did not                                                                                                                                                                                       
  // write (Markdown, RichTextEditor, DriverJs with allowHtml). DOMPurify's                                                                                                                                                                                    
  // default allowlist is about script, not about phishing or page takeover:                                                                                                                                                                                   
  // it keeps <form>, <button>, <select>, <textarea>, the attributes action,                                                                                                                                                                                   
  // formaction and form, and <style>. A prompt-injected LLM answer or one                                                                                                                                                                                     
  // user's stored text could then draw a fake logon form that posts                                                                                                                                                                                           
  // anywhere, or restyle and hide the whole abap2UI5 page - a <style> element                                                                                                                                                                                 
  // is not scoped to the control. <input> stays: marked renders a GFM task                                                                                                                                                                                    
  // list item as <input type="checkbox" disabled>, and without a form, a                                                                                                                                                                                      
  // form attribute or a button an input cannot send anything.                                                                                                                                                                                                 
  const PURIFY = Object.freeze({                                                                                                                                                                                                                               
    FORBID_TAGS: ["style", "form", "button", "select", "option", "textarea"],                                                                                                                                                                                  
    FORBID_ATTR: ["action", "formaction", "form"],                                                                                                                                                                                                             
  });                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
  // HTML through DOMPurify with PURIFY. The caller has loaded DOMPurify.                                                                                                                                                                                      
  const purify = (html) => window.DOMPurify.sanitize(String(html ?? ""), PURIFY);                                                                                                                                                                              
                                                                                                                                                                                                                                                               
  // Comma separated attribute value -> trimmed, non-empty list. XML views                                                                                                                                                                                     
  // hand array-typed properties over as strings, so the controls take plain                                                                                                                                                                                   
  // strings and split them here.                                                                                                                                                                                                                              
  const toList = (val) =>                                                                                                                                                                                                                                      
    String(val || "")                                                                                                                                                                                                                                          
      .split(",")                                                                                                                                                                                                                                              
      .map((entry) => entry.trim())                                                                                                                                                                                                                            
      .filter(Boolean);                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
  return {                                                                                                                                                                                                                                                     
    integrityOf,                                                                                                                                                                                                                                               
    isDestroyed,                                                                                                                                                                                                                                               
    loadScript,                                                                                                                                                                                                                                                
    loadScripts,                                                                                                                                                                                                                                               
    loadStyle,                                                                                                                                                                                                                                                 
    logError,                                                                                                                                                                                                                                                  
    ownerView,                                                                                                                                                                                                                                                 
    PURIFY,                                                                                                                                                                                                                                                    
    purify,                                                                                                                                                                                                                                                    
    resolveControl,                                                                                                                                                                                                                                            
    toCssSize,                                                                                                                                                                                                                                                 
    toList,                                                                                                                                                                                                                                                    
    triggerFired,                                                                                                                                                                                                                                              
  };                                                                                                                                                                                                                                                           
});                                                                                                                                                                                                                                                            